'use client'

/**
 * The level badge (2026-11-05 v4, user: "still not good — think like an Apple or Google designer"): one vector medal per
 * level — a metal ring, a face in the tier's colour, the level numeral pressed into it. Graphite · silver · gold ·
 * platinum · sapphire · black with a silver ring · black with a gold ring; L4+ gain a fine engraved track, L6+ a second.
 * The number makes the rank readable at 16px; the metal makes it feel earned. Files: public/media/membership/
 * badge-L{n}.svg, generated by G:/Media/a-reit-levels/tools/badges.py. Same look in light and dark.
 */
export const gemSrc = (level: number) => `/media/membership/badge-L${Math.min(7, Math.max(1, Math.round(level || 1)))}.svg`

export function Medallion({ level, size = 64, className }: { level: number; size?: number; className?: string }) {
  return <img src={gemSrc(level)} alt="" width={size} height={size} className={className} draggable={false} decoding="async" aria-hidden="true" />
}
